import { useEffect, useState } from "react";
import { useUIAppState } from "../../context/ui-appState";
import { t } from "../../i18n";
import { useApp } from "../App";
import { Dialog } from "../dialogs/Dialog";
import { withInternalFallback } from "../hoc/withInternalFallback";
import MermaidToJsonDraw from "./MermaidToJsonDraw";
import MdToTable from "./MdToTable";
import "./TTDDialog.scss";
import { TTDDialogTab } from "./TTDDialogTab";
import { TTDDialogTabTrigger } from "./TTDDialogTabTrigger";
import { TTDDialogTabTriggers } from "./TTDDialogTabTriggers";
import TTDDialogTabs from "./TTDDialogTabs";
import { TTDWelcomeMessage } from "./TTDWelcomeMessage";
import TextToDiagram from "./TextToDiagram";
import type { MermaidToJsonDrawLibProps, TTDPersistenceAdapter, TTTDDialog } from "./types";

export const TTDDialog = (
  props:
    | {
        onTextSubmit: TTTDDialog.onTextSubmit;
        renderWelcomeScreen?: TTTDDialog.renderWelcomeScreen;
        renderWarning?: TTTDDialog.renderWarning;
        persistenceAdapter: TTDPersistenceAdapter;
      }
    | { __fallback: true }
) => {
  const appState = useUIAppState();

  if (appState.openDialog?.name !== "ttd") {
    return null;
  }

  return <TTDDialogBase {...props} tab={appState.openDialog.tab} />;
};

TTDDialog.WelcomeMessage = TTDWelcomeMessage;

/**
 * Text to diagram (TTD) dialog
 */
const TTDDialogBase = withInternalFallback(
  "TTDDialogBase",
  ({
    tab,
    ...rest
  }: {
    tab: "text-to-diagram" | "mermaid" | "md-to-table";
  } & (
    | {
        onTextSubmit(props: TTTDDialog.OnTextSubmitProps): Promise<TTTDDialog.OnTextSubmitRetValue>;
        renderWelcomeScreen?: TTTDDialog.renderWelcomeScreen;
        renderWarning?: TTTDDialog.renderWarning;
        persistenceAdapter: TTDPersistenceAdapter;
      }
    | { __fallback: true }
  )) => {
    const app = useApp();

    const [mermaidToJsonDrawLib, setMermaidToJsonDrawLib] = useState<MermaidToJsonDrawLibProps>({
      loaded: false,
      api: import("@excalidraw/mermaid-to-excalidraw"),
    });

    useEffect(() => {
      const fn = async () => {
        await mermaidToJsonDrawLib.api;
        setMermaidToJsonDrawLib(prev => ({ ...prev, loaded: true }));
      };
      fn();
    }, [mermaidToJsonDrawLib.api]);

    return (
      <Dialog
        className="ttd-dialog"
        onCloseRequest={() => {
          app.setOpenDialog(null);
        }}
        size={1520}
        title={false}
        {...rest}
        autofocus={false}
      >
        <TTDDialogTabs dialog="ttd" tab={tab}>
          {"__fallback" in rest && rest.__fallback ? (
            <p className="dialog-mermaid-title">{t("mermaid.title")}</p>
          ) : (
            <TTDDialogTabTriggers>
              <TTDDialogTabTrigger tab="text-to-diagram">
                <div className="ttd-dialog-tab-trigger__content">
                  {t("labels.textToDiagram")}
                  <div className="ttd-dialog-tab-trigger__badge">{t("chat.aiBeta")}</div>
                </div>
              </TTDDialogTabTrigger>
              <TTDDialogTabTrigger tab="mermaid">{t("mermaid.label")}</TTDDialogTabTrigger>
              <TTDDialogTabTrigger tab="md-to-table">{t("mdToTable.label")}</TTDDialogTabTrigger>
            </TTDDialogTabTriggers>
          )}

          {!("__fallback" in rest) && (
            <TTDDialogTab className="ttd-dialog-content" tab="text-to-diagram">
              <TextToDiagram
                mermaidToJsonDrawLib={mermaidToJsonDrawLib}
                onTextSubmit={rest.onTextSubmit}
                renderWelcomeScreen={rest.renderWelcomeScreen}
                renderWarning={rest.renderWarning}
                persistenceAdapter={rest.persistenceAdapter}
              />
            </TTDDialogTab>
          )}
          <TTDDialogTab className="ttd-dialog-content" tab="mermaid">
            <MermaidToJsonDraw
              mermaidToJsonDrawLib={mermaidToJsonDrawLib}
              isActive={tab === "mermaid"}
            />
          </TTDDialogTab>
          <TTDDialogTab className="ttd-dialog-content" tab="md-to-table">
            <MdToTable isActive={tab === "md-to-table"} />
          </TTDDialogTab>
          {tab === "text-to-diagram" && (
            <div className="ttd-dialog-warning">
              AI may be inaccurate. Please review the generated diagram carefully before inserting it
              into your canvas.{" "}
              <a href="https://llm.chila.io.vn/" target="_blank" rel="noopener noreferrer">
                API powered by Chila.io.vn
              </a>
            </div>
          )}
        </TTDDialogTabs>
      </Dialog>
    );
  }
);
